import java.util.HashMap;
import java.util.Map;

public class Drill {
    static String run() {
        String[] words = {"b", "a", "b", "c", "b", "a"};
        Map<String, Integer> m = new HashMap<>();
        for (String w : words) {
            m.merge(w, 1, Integer::sum);
        }
        int b = m.get("b");
        boolean hasZ = m.containsKey("z");
        int z = m.getOrDefault("z", 0);
        m.remove("c");
        m.putIfAbsent("d", 7);
        @@BLANK@@
        return b + " " + hasZ + " " + z + " " + m.size() + " " + m.get("a") + " " + m.get("d");
    }

    static int bad = 0;
    static void check(Object got, Object exp) {
        String g = String.valueOf(got), e = String.valueOf(exp);
        if (!g.equals(e)) { bad++; System.out.println("FAIL: got " + g + " expected " + e); }
    }
    static void done() { if (bad == 0) System.out.println("PASS"); }

    public static void main(String[] args) {
        check(run(), "3 false 0 3 10 7");
        done();
    }
}
